-- foods_v27.sql — gap-fill for common Indian raw ingredients + Hindi/Hinglish aliases.
-- Generated by scripts/import-foods-gapfill.mjs. Idempotent (ON CONFLICT DO NOTHING). NOT applied automatically.
-- Sources: USDA FoodData Central Foundation Foods (public domain/CC0) for new raw-ingredient rows tagged
-- 'usda_foundation'; one manually-verified USDA SR Legacy fact (besan) tagged 'usda'. All other rows referenced
-- by the new food_aliases already exist in production (ifct/usda/dish/custom, imported by scripts/import-foods.mts).

on conflict (id) do nothing;

on conflict (alias) do nothing;

-- Data fixes found in review (2026-09-25): IFCT fats/oils were imported with energy = 0.
update bandlog.foods set calories = 900
 where source = 'ifct' and coalesce(calories,0) = 0 and fat_g >= 99
   and (id like 'ifct-%oil%' or id in ('ifct-ghee','ifct-vanaspati'));
-- Chicken leg, skinless (raw): stored 383.6 kcal; Atwater from its own macros (p 19.4, f 12.6) = 191.
update bandlog.foods set calories = 191 where id = 'ifct-chicken-poultry-leg-skinless' and calories > 300;
